/// Dispatch a MGGA functional by enum -- delegates to by-id routing.
pub fn dispatch_mgga(
    functional: libxc_core::model::MggaFunctional,
    input: &libxc_core::input::MggaInput<'_>,
    output: &mut libxc_core::output::MggaOutput<'_>,
    order: libxc_core::model::DerivativeOrder,
    spin: libxc_core::model::Spin,
    thresholds: &libxc_core::model::Thresholds,
) -> Result<(), libxc_core::error::LibxcRsError> {
    dispatch_mgga_by_id(functional.to_id(), input, output, order, spin, thresholds)
}
